package com.vault.dto;import com.vault.entity.*;import java.time.Instant;import java.util.UUID;public final class Views{private Views(){}public record UserView(UUID id,String name,String email){public static UserView from(User u){return new UserView(u.getId(),u.getName(),u.getEmail());}}public record AuthView(String token,UserView user){}public record KeyView(UUID id,String serviceName,String keyName,String environment,String maskedKey,String status,String description,Instant expiresAt,Instant createdAt,Instant lastUsedAt){public static KeyView from(ApiKey k){return new KeyView(k.getId(),k.getServiceName(),k.getKeyName(),k.getEnvironment(),"••••••••••••",k.effectiveStatus(),k.getDescription(),k.getExpiresAt(),k.getCreatedAt(),k.getLastUsedAt());}}public record ActivityView(UUID id,String action,String description,Instant createdAt){public static ActivityView from(ActivityLog a){return new ActivityView(a.getId(),a.getAction(),a.getDescription(),a.getCreatedAt());}}public record Stats(long total,long active,long expiringSoon,long services){}}
